css:
[data-theme="dashy-dark"] .section.tinted .card{
  /* Dashy teinte le fond de la tuile et pose une ombre dessous ; le melange
     garde le texte lisible quelle que soit la teinte choisie. */
  background:color-mix(in srgb, var(--tile-color) 22%, var(--surface));
  border-color:color-mix(in srgb, var(--tile-color) 45%, var(--border));
  box-shadow:0 2px 6px rgba(0,0,0,.35);
  transition:transform .12s ease,box-shadow .12s ease,background .12s ease;
}

[data-theme="dashy-dark"] .section.tinted .card:hover{
  background:color-mix(in srgb, var(--tile-color) 30%, var(--surface));
  box-shadow:0 4px 12px rgba(0,0,0,.45);
}

/* Effet bouton : la tuile s'enfonce au clic. translateY compense l'ombre
   pour que la bascule paraisse venue du fond et non d'un glissement. */
[data-theme="dashy-dark"] .section.tinted .card:active{
  transform:translateY(1px);
  box-shadow:0 1px 2px rgba(0,0,0,.4);
}

[data-theme="dashy-dark"] .service-icon{
  filter:none !important;
  opacity:1;
}

[data-theme="dashy-dark"] .section-header{
  color:var(--muted);
}

[data-theme="dashy-dark"] .category-icon{
  color:var(--tile-color, var(--accent));
}
